// Generator for tests/fixtures/parser-divergence/anchored-empty-key-p0-16/expected.json
// (FIX-P0-16). Runs the TypeScript parseWorkflowYaml on every fixture and
// prints {id: {status, errors, events}} as JSON. The Oracle half is
// generated by gen-expected-p0-16.py (scripts/oracle-parse-probe.py per
// fixture); the two halves are merged into expected.json by hand (or by
// that script) and the test asserts both sides match the recording AND
// each other. Run with:
//   ./node_modules/.bin/esbuild evidence/probes/fix-p0-16/gen-expected-p0-16.ts \
//     --bundle --platform=node --format=esm --outfile=/tmp/gen-expected-p0-16.mjs
//   node /tmp/gen-expected-p0-16.mjs
import { readFileSync, readdirSync } from "node:fs";
import { join } from "node:path";
import { parseWorkflowYaml } from "../../../src/core/workflow-parser.js";

const dir = "tests/fixtures/parser-divergence/anchored-empty-key-p0-16";
const files = readdirSync(dir).filter((f) => f.endsWith(".yml")).sort();
const out: Record<string, unknown> = {};
for (const f of files) {
  const id = f.replace(".yml", "");
  const text = readFileSync(join(dir, f), "utf-8");
  const ts = parseWorkflowYaml(text, id);
  out[id] = { status: ts.status, errors: ts.errors, events: ts.events };
}
console.log(JSON.stringify(out, null, 1));
